data.solution:
chomp(my $tour = <STDIN>);

my @cube=(0,1,3,2,4,5,7,6);
my @length=(0,1,sqrt 2,sqrt 5);
my $length=0;
my $from;

for my $to (map{$cube[$_-1]} split(//,$tour)) {
    $length += $length[unpack('%32b*',pack('C',$from^$to))] if(defined $from);
    $from = $to;
}

printf("%.3f\n",$length);
